def conceder_permissoes(apps, schema_editor):
    """Cria as permissões do módulo (o Django só as cria depois do migrate) e as concede aos perfis padrão JÁ existentes, só acrescentando."""
    from django.apps import apps as django_apps
    from django.contrib.auth.management import create_permissions

    create_permissions(django_apps.get_app_config("precificacaoservico"), apps=apps, verbosity=0)
    Permission, Group = apps.get_model("auth", "Permission"), apps.get_model("auth", "Group")
    for nome, codenames in PERMISSOES.items():
        grupo = Group.objects.filter(name=nome).first()
        if grupo:
            grupo.permissions.add(*Permission.objects.filter(content_type__app_label="precificacaoservico", codename__in=codenames))



